INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-overview', 'campsite', '揪好森露營區是什麼樣的地方？', '露營區介紹|豪華露營|桃園露營|楊梅露營|圓頂帳篷|免搭帳|在哪裡|位置', '揪好森位於桃園楊梅，是全場僅兩帳的森林豪華露營空間。熱氣球房與雲朵房各有專屬草地、戶外廚房、獨立衛浴與活動區，不需要自己搭帳。', 'https://camp.8-ways.com/', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-availability', 'campsite', '哪些日期有空房？', '空房|檔期|有房|有空|可住日期|哪天可以', '可直接查詢即時空房與價格；系統只顯示房型日期狀態，不會公開客人資料。正式保留仍要完成預訂資料與訂金確認。', 'https://camp.8-ways.com/pages/availability.html', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-rooms', 'campsite', '有哪些房型？', '房型|幾間房|幾個帳篷|熱氣球房|雲朵房|兩帳', '全場只有熱氣球房與雲朵房兩個房型。兩房都是直徑約 7 公尺的圓頂帳篷，但空間、床型與娛樂設備各有特色。', 'https://camp.8-ways.com/#rooms', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-capacity', 'campsite', '一間可以住幾個人？', '幾人|入住人數|最多幾人|六人|四人|容量', '熱氣球房與雲朵房都可安排 1～6 人入住，4 人最舒適；第 5、6 位會加設一張雙人床墊。', 'https://camp.8-ways.com/', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-balloon-beds', 'campsite', '熱氣球房床型是什麼？', '熱氣球房床型|熱氣球房有幾張床|沙發床|雙人床|床墊|六個人睡', '熱氣球房有 1 張雙人床、1 張雙人沙發床；第 5、6 位入住時再加設 1 張雙人床墊。', 'https://camp.8-ways.com/pages/balloon-tent', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-cloud-beds', 'campsite', '雲朵房床型是什麼？', '雲朵房床型|雲朵房有幾張床|兩張雙人床|床墊|六個人睡', '雲朵房有 2 張雙人床；第 5、6 位入住時再加設 1 張雙人床墊。', 'https://camp.8-ways.com/pages/cloud-tent', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-checkin', 'campsite', '幾點入住、幾點退房？', '入住時間|退房時間|幾點入住|幾點退房|check in|check out', '下午 3:00 入住，中午 12:00 退房，平日與假日相同。提早入住或延後退房屬於特殊安排，小編會再幫您跟老闆確認。', 'https://camp.8-ways.com/pages/faq.html', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-weekday-private', 'campsite', '平日一房就是包場嗎？', '平日包場|一房包場|星期一|星期二|星期三|星期四|另一房', '週一至週四預訂其中一個房型，住宿期間不再接待另一組客人；未預訂的另一房不開放使用，因此是一房包場。', 'https://camp.8-ways.com/', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-weekend-zone', 'campsite', '假日一房是包場嗎？', '假日包場|週五|週六|週日|星期五|星期六|星期日|一房包區|兩房包場', '週五、週六、週日與連續假期，一房是包自己的專屬區域；同日分別預訂熱氣球房與雲朵房，才是全場兩房包場。', 'https://camp.8-ways.com/', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-balloon-price', 'campsite', '熱氣球房多少錢？', '熱氣球房價格|熱氣球房費用|熱氣球房多少錢|熱氣球房一般多少錢|5800|房價', '一般日期熱氣球房官網直訂參考價為 NT$5,800。連假、跨年與春節等特殊日期請以空房日曆顯示及正式確認為準。', 'https://camp.8-ways.com/pages/balloon-tent', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-cloud-price', 'campsite', '雲朵房多少錢？', '雲朵房價格|雲朵房費用|雲朵房多少錢|雲朵房打卡優惠|5000|打卡優惠|房價', '雲朵房一般日期頁面標示原價 NT$7,800、打卡優惠參考 NT$5,000；優惠條件與特殊日期價格以預訂時確認為準。', 'https://camp.8-ways.com/pages/cloud-tent', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-two-room-price', 'campsite', '兩房包場有折扣嗎？', '兩房包場|兩帳包場|包場價格|包場折扣|兩間一起', '熱氣球房與雲朵房分別預訂、分別計價；同日完成兩房預訂就是全場包場，總費用依兩房當日價格相加，官網目前未標示額外包場折扣。', 'https://camp.8-ways.com/', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-balloon-facilities', 'campsite', '熱氣球房有哪些設備？', '熱氣球房設備|電視|Apple TV|Switch|麻將|戶外投影|大螢幕', '熱氣球房有冷暖氣、Wi-Fi、電視、Apple TV、Switch 2、藍牙音響、卡拉 OK、電動麻將桌，以及草地戶外投影與大螢幕。', 'https://camp.8-ways.com/pages/balloon-tent', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-cloud-facilities', 'campsite', '雲朵房有哪些設備？', '雲朵房設備|雲朵房有浴缸|浴缸|投影|電影|藍牙音響|景觀浴缸', '雲朵房有冷暖氣、Wi-Fi、帳內景觀浴缸、獨立衛浴、室內投影機、藍牙音響與卡拉 OK，適合想安靜泡澡、看電影的客人。', 'https://camp.8-ways.com/pages/cloud-tent', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-kitchen', 'campsite', '可以自己煮東西或烤肉嗎？', '煮東西|廚房|烤肉|BBQ|卡式爐|冰箱|微波爐|餐具', '兩個房型都有專屬戶外廚房、冰箱、微波爐、卡式爐、美式烤肉爐，以及基本鍋具、餐具與清潔用品；餐點與食材需自行準備。', 'https://camp.8-ways.com/pages/facilities.html', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-food', 'campsite', '有附晚餐或早餐嗎？', '早餐|晚餐|餐點|食材|附餐|吃飯', '住宿不包含餐點與食材，請自行準備晚餐、早餐與喜歡的食材；附近生活機能方便，可在入住前先採買。', 'https://camp.8-ways.com/pages/faq.html', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-bathroom', 'campsite', '有獨立衛浴和備品嗎？', '衛浴|浴室|廁所|浴巾|吹風機|洗髮精|牙刷', '兩房都有各自的獨立衛浴，提供浴巾、吹風機、洗髮精、沐浴乳與牙刷。雲朵房另有帳內景觀浴缸；熱氣球房不含浴缸。', 'https://camp.8-ways.com/pages/facilities.html', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-pet', 'campsite', '可以帶寵物嗎？', '寵物|毛孩|狗狗|貓咪|寵物友善|帶狗', '兩個房型都歡迎毛孩，預訂時請告知種類、數量與體型；入住前請完成基本清潔與梳毛，毛孩請勿上床、沙發及寢具，並由主人全程照顧。', 'https://camp.8-ways.com/pages/faq.html', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-children', 'campsite', '可以帶小孩或嬰兒嗎？', '小孩|兒童|嬰兒|嬰幼兒|親子|年齡', '可以，露營區適合親子同行；預訂時請主動告知嬰幼兒年齡與實際入住人數，方便小編協助確認床位與安排。', 'https://camp.8-ways.com/pages/faq.html', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-ktv', 'campsite', '可以唱卡拉 OK 到幾點？', '卡拉OK|KTV|唱歌|麥克風|晚上十點|音量', '兩房都有卡拉 OK 與無線麥克風。若另一房有住客，晚上 10:00 至隔天中午 12:00 請勿唱歌；兩帳包場時不受這項共住限制，但仍請注意合理音量。', 'https://camp.8-ways.com/pages/faq.html', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-smoking', 'campsite', '房內可以抽菸嗎？', '抽菸|吸菸|禁菸|菸蒂|室內', '帳篷與所有室內空間全面禁菸。如需吸菸請到指定戶外位置，並妥善熄滅、清理菸蒂。', 'https://camp.8-ways.com/pages/faq.html', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-mosquito', 'campsite', '森林裡蚊蟲會不會很多？', '蚊子|蚊蟲|防蚊|小黑蚊|蚊香|滅蚊燈', '戶外自然環境仍會有蚊蟲。帳篷與草地設有滅蚊燈，戶外也備有蚊香盒、蚊香及香茅環境噴霧；仍建議自行準備個人習慣的防蚊用品。', 'https://camp.8-ways.com/pages/summer-mosquito-prevention.html', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-parking', 'campsite', '可以停幾台車、怎麼到？', '停車|幾台車|地址|導航|怎麼去|交通', '完成預訂後會提供詳細地址、導航、停車與自助入住資訊。若車輛較多或有大型車，請在預訂時先告訴小編確認安排。', 'https://camp.8-ways.com/pages/booking.html', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-party', 'campsite', '可以辦生日、抓周或派對嗎？', '派對|生日|慶生|抓周|求婚|紀念日|聚會|場地', '可以，場地適合抓周、慶生、求婚、紀念日、寵物聚會、野餐與小型活動；可選住宿或不住宿的時租活動方案，實際人數、時段與設備需再確認。', 'https://camp.8-ways.com/pages/party-event-space.html', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-party-price', 'campsite', '不住宿的活動場地怎麼計費？', '活動場地價格|時租|單區|雙區|不住宿|包場活動', '官網一般參考為單區平日 NT$880／小時起、雙區平日 NT$1,480／小時起；實際費用會依日期、時段、人數、佈置、清潔與設備需求確認。', 'https://camp.8-ways.com/pages/party-event-space.html', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-decoration', 'campsite', '有幫忙佈置派對嗎？', '佈置|氣球|花牆|抓周佈置|生日佈置|求婚佈置', '場地有適合拍照與簡單佈置的草地、花牆與活動空間；客製佈置是否能協助、進場時間與費用屬於特殊需求，小編會幫您跟老闆確認。', 'https://camp.8-ways.com/pages/party-event-space.html', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-rain', 'campsite', '下雨天還能入住或辦活動嗎？', '下雨|雨天|颱風|室內|延期|天氣', '圓頂帳篷內、獨立衛浴與部分料理空間可正常使用，但草地活動與戶外投影會受天候影響。若涉及延期、取消或特殊安排，小編會依實際天候跟老闆確認。', 'https://camp.8-ways.com/pages/faq.html', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-booking-data', 'campsite', '想預訂要提供什麼？', '預訂資料|怎麼預約|訂房|要提供什麼|下訂', '請提供入住日期、房型、成人與兒童人數、停車車數、寵物、訂房姓名、電話與特殊需求。小編整理後會再跟老闆確認檔期、費用與預訂步驟。', 'https://camp.8-ways.com/pages/booking.html', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-discount', 'campsite', '可以算便宜一點嗎？', '太貴|便宜一點|折扣|殺價|優惠|議價', '謝謝您直接告訴小編預算考量。官網方案已整理目前公開價格；若有特定日期、人數或活動需求，小編可以先幫您整理，再跟老闆確認是否有適合的方案，但無法先保證額外折扣。', 'https://camp.8-ways.com/pages/availability.html', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('camp-contact', 'campsite', '怎麼聯絡你們？', '電話|聯絡|客服|LINE|WhatsApp|Instagram', '可以直接在這個 LINE 留言，或來電 0911-252-302；也可從官網查看房型、空房與活動方案。', 'https://camp.8-ways.com/', 'knowledge/line/campsite.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-overview', 'campervan', '露營車是什麼服務？', '露營車出租|自走式|服務介紹|第一次租|新手', '揪好森提供自排自走式大型露營車出租，台北以到府或約定地點交車為主，桃園、新竹可洽詢。交車時約有 30 分鐘實車教學，第一次租也能循序上手。', 'https://van.joyforest.tw/', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-availability', 'campervan', '哪些日期有空？', '檔期|有空|空檔|可租日期|哪天可以|查看日期', '可直接查詢即時檔期；系統只顯示可預約、可候補、已預訂或不可預訂，不會公開客人資料。正式保留仍要完成預訂資料與訂金確認。', 'https://van.joyforest.tw/pages/availability', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-minimum-rental', 'campervan', '最低租幾天？', '最低租期|最低要租幾天|最少幾天|最少要租幾天|兩天一夜|三天兩夜|48小時', '最低租期是 3 天 2 夜／48 小時。露營車需要時間熟悉設備、安排停靠與享受慢旅行，2 天 1 夜通常會太趕。', 'https://van.joyforest.tw/pages/campervan', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-price', 'campervan', '租金多少？', '價格|租金|費用|多少錢|平日|假日|連假', '平日 3 天 2 夜／48 小時 NT$11,800 起，假日 NT$13,800 起，連假與特殊節日 NT$17,800 起。實際總額依日期、交還車時間、送車地點、租期與加購內容確認。', 'https://van.joyforest.tw/pages/campervan', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-extra-day', 'campervan', '加租一天多少？', '加一天|加租一天|延長一天|加天|多租一天|續租', '一般平日加一天參考 NT$2,800，假日加一天參考 NT$4,800；連假、跨日類型與特殊檔期須按完整租期重新計算。', 'https://van.joyforest.tw/pages/campervan', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-security-deposit', 'campervan', '押金多少、做什麼用？', '押金|保證金|退押金|ETC|停車費|結算', '現行押金為 NT$5,000，用於 ETC、停車、燃油、清潔、遺失、設備或車損等還車後結算；扣除有紀錄的實際費用後退還餘額。押金不是事故責任上限。', 'https://van.joyforest.tw/pages/campervan-insurance', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-license', 'campervan', '需要什麼駕照？', '駕照|普通駕照|小客車駕照|自排|可以開嗎', '一般小客車駕照即可駕駛，車輛是自排、自走式露營車，不需要拖車駕照。', 'https://van.joyforest.tw/pages/campervan', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-size-height', 'campervan', '車子多大、車高多少？', '車高|車長|車寬|尺寸|限高|地下停車場', '車長約 5 公尺、車寬約 2 公尺、車高約 3 公尺。請避開地下停車場、低雨遮、棚架與限高不足處；不確定時先停車下車確認。', 'https://van.joyforest.tw/pages/booking-guide/driving-safety', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-seats', 'campervan', '可以坐幾個人？', '幾人|坐幾個|乘坐|安全帶|合法座位|六人', '合法乘坐 6 人。行駛時所有乘客都必須坐在 6 個合法座位並繫安全帶；後方生活與餐桌區只能在停車後使用。', 'https://van.joyforest.tw/pages/booking-guide/beds', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-beds', 'campervan', '有幾張床、可以睡幾人？', '幾張床|睡幾人|床位|雙人床|變床|四大兩小|五位成人', '車內有 2 張雙人床，一張固定額頭床、一張由餐桌區變形。建議睡 5 位成人，或 4 位成人加 2 位兒童。', 'https://van.joyforest.tw/pages/booking-guide/beds', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-bathroom', 'campervan', '車上可以洗澡、有廁所嗎？', '洗澡|衛浴|廁所|馬桶|熱水|浴室', '車內有簡易衛浴、冷熱水、馬桶與洗手台，適合基本沖洗；若要長時間淋浴，建議搭配有衛浴與補水設備的露營區。', 'https://van.joyforest.tw/pages/booking-guide/water-bathroom-toilet', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-water', 'campervan', '清水有多少、怎麼補水？', '水箱|清水|補水|110公升|外接水|沖腳', '清水箱約 110 公升，可供基本盥洗與簡短沖洗。長途旅行建議每隔一至兩晚安排可補水、接電與洗澡的露營區。', 'https://van.joyforest.tw/pages/booking-guide/water-bathroom-toilet', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-aircon', 'campervan', '有冷氣嗎、可以開多久？', '冷氣|暖氣|空調|開多久|夏天|冬天', '車內有冷暖氣。單靠車內電池、強力運轉時通常約 8～10 小時；長時間使用建議接露營區外電，並在白天行車或停靠時持續補電。', 'https://van.joyforest.tw/pages/booking-guide/power-air-conditioning', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-power', 'campervan', '露營車怎麼充電？', '充電|接電|電量|電池|發電機|外接電源|跳電', '可在露營區接外電，也可用車載發電機補電。露營車用電適合邊用邊補，不要等到快沒電才處理；露營區供電較弱時要降低充電速度以避免跳電。', 'https://van.joyforest.tw/pages/booking-guide/power-air-conditioning', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-generator', 'campervan', '有發電機嗎？', '發電機|外置發電機|Yamaha|夜間冷氣|戶外通風', '車上有內建發電機；外置發電機不是標準配備，有需要請在預約時提出。發電機只能在戶外、通風、平坦且遠離車身與帳篷入口處使用，嚴禁在車內或密閉空間啟動。', 'https://van.joyforest.tw/pages/booking-guide/power-air-conditioning', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-fridge-kitchen', 'campervan', '有冰箱、爐具和餐具嗎？', '冰箱|冷凍|卡式爐|餐具|廚房|煮東西|料理', '車內有約 70L 冷藏冷凍冰箱、卡式爐、基本餐具與簡易料理空間，可準備早餐、咖啡、熱湯或簡單露營料理；目前沒有微波爐。', 'https://van.joyforest.tw/pages/campervan', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-mileage-fuel', 'campervan', '有里程限制嗎、加什麼油？', '里程|不限里程|油料|柴油|滿油還車', '基本方案包含不限里程。露營車使用柴油，還車時依約定補回油量；油料、ETC 與停車費通常於還車後依實際使用結算。', 'https://van.joyforest.tw/pages/booking-guide', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-delivery', 'campervan', '可以送車到哪裡？', '到府交車|送車|交車地點|台北|桃園|新竹|台中', '以台北到府或約定地點交車為主，桃園、新竹可洽詢；其他地區須依租期、地點與當次安排確認。', 'https://van.joyforest.tw/booking', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-handover', 'campervan', '交車會教學嗎？', '交車教學|交車時會教|教我操作|怎麼操作|不會用|新手教學|多久', '交車時會用實車進行約 30 分鐘基本教學，包含駕駛注意、床鋪、電力、冷暖氣、冰箱、水箱、衛浴、外接電與還車檢查。', 'https://van.joyforest.tw/pages/booking-guide', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-video-guide', 'campervan', '有操作教學影片嗎？', '教學影片|操作影片|怎麼使用|使用說明|預習', '有，官網把整體導覽、駕駛安全、電力冷氣、水與衛浴、戶外影音、床鋪變形分成六個主題，可依需要逐頁查看。', 'https://van.joyforest.tw/pages/booking-guide', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-parking-overnight', 'campervan', '可以停一般停車場過夜嗎？', '車宿|過夜|停車場|免費露營|海邊過夜|路邊', '只能選擇現場公告或管理方明確允許過夜的地點。非露營區請把桌椅、車邊帳、料理設備留在車內，遵守現場規定，不排放污水也不製造噪音。', 'https://van.joyforest.tw/pages/booking-guide', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-campsite', 'campervan', '一定要住露營區嗎？', '露營區|營地|一定要住|水電|第一晚|過夜安排', '不一定，但第一次使用建議至少一半行程住有水電、衛浴與人員協助的正規露營區，會更容易補水、接電、洗澡與熟悉設備。', 'https://van.joyforest.tw/pages/booking-guide', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-pet', 'campervan', '可以帶寵物嗎？', '寵物|狗狗|貓咪|毛孩|清潔費', '可攜帶中小型犬，但要事先告知並完成基本美容；寵物清潔費為 NT$800／次，其他細節以預約確認為準。', 'https://van.joyforest.tw/pages/booking-guide', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-smoking', 'campervan', '車內可以抽菸嗎？', '抽菸|吸菸|煙|禁菸|清潔費', '全車禁菸。違反禁菸規定的清潔費為 NT$2,000～6,000，並可能依實際損害另行處理。', 'https://van.joyforest.tw/pages/booking-guide', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-rain', 'campervan', '下雨天可以使用嗎？', '下雨|雨天|颱風|戶外設備|淋雨', '下雨時車內可正常使用；戶外桌椅、燈串、投影與其他電子設備請避免淋雨。若遇天候警報或道路風險，行程與安全安排需另行確認。', 'https://van.joyforest.tw/pages/booking-guide', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-addons', 'campervan', '有戶外露營或影音套組嗎？', '網美套組|影音套組|投影|布幕|Switch|卡拉OK|桌椅|燈串', '可選網美露營套組與影音娛樂套組，參考加購價合計 NT$3,800；可能包含戶外桌椅、燈串、投影、布幕、藍牙喇叭、Switch 與卡拉 OK，實際品項與費用依當次庫存及報價確認。', 'https://van.joyforest.tw/pages/campervan', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-insurance', 'campervan', '露營車有保險嗎？', '保險|保障|第三責任|超額責任|車體險|乘客險', '車輛有汽車相關保障，包含第三人及乘客超額責任每次事故合計最高 NT$2,000 萬、第三人責任、乘客責任、駕駛人傷害與車體乙式等；實際理賠仍依事故日有效保單、條款與保險公司審核。', 'https://van.joyforest.tw/pages/campervan-insurance', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-damage', 'campervan', '撞到或刮傷怎麼辦？', '車損|刮傷|撞到|事故|賠償|修理|報警', '先確保人員安全、立即報警並通知揪好森，不要私下和解。符合契約與保險條件的一般承保車體碰撞，承租人責任每次事故最高 NT$10,000；露營車廂、車頂、內裝與設備則依實際修復或更換成本處理。', 'https://van.joyforest.tw/pages/campervan-insurance', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-viewing', 'campervan', '租之前可以現場看車嗎？', '看車|現場看車|參觀|試看|試駕', '目前不提供現場看車；可先看官網的車內實景、設備規格與操作教學，正式交車時會再用實車完整導覽。', 'https://van.joyforest.tw/pages/campervan', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-booking-data', 'campervan', '詢問預訂需要提供什麼資料？', '預約資料|要提供什麼|怎麼預約|下訂資料|訂車', '請提供姓名、手機、租借日期與天數、大人與小孩人數、寵物、送車地點、預計旅遊方向，以及是否需要戶外或影音套組。檔期與正式費用確認後再進入預訂程序。', 'https://van.joyforest.tw/booking', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-self-drive', 'campervan', '有司機接送嗎？', '司機|接送|包車|代駕|自駕|自己開', '這是自駕露營車出租，不是含司機的包車行程。揪好森會把車送到約定地點並完成教學，旅途中由客人自行駕駛。', 'https://van.joyforest.tw/', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
INSERT INTO line_knowledge (id, service, question, keywords, answer, url, source_file, updated_at, enabled) VALUES ('van-return', 'campervan', '還車前要做什麼？', '還車|還車檢查|垃圾|油量|收納|退押金', '請帶走個人物品、整理垃圾、把餐具與戶外設備放回原位、關閉水電，並依約定補回柴油；ETC、停車費與其他費用於還車後結算。', 'https://van.joyforest.tw/pages/booking-guide', 'knowledge/line/campervan.md', '2026-10-16', 1) ON CONFLICT(id) DO UPDATE SET service=excluded.service, question=excluded.question, keywords=excluded.keywords, answer=excluded.answer, url=excluded.url, source_file=excluded.source_file, updated_at=excluded.updated_at, enabled=1;
